// Clean-room exhaustive solver for bounded weighted popular matchings.
#include <cstddef>
#include <cstdint>
namespace {constexpr std::size_t N=4,F=6;bool decode(std::uint64_t code,std::size_t n,std::size_t m,int*a){unsigned used=0;for(std::size_t i=0;i<n;++i){auto digit=static_cast<std::size_t>(code%(m+1));code/=m+1;a[i]=static_cast<int>(digit)-1;if(digit&&((used>>(digit-1))&1u))return false;if(digit)used|=1u<<(digit-1);}return true;}bool lexless(const int*a,const int*b,std::size_t n){for(std::size_t i=0;i<n;++i)if(a[i]!=b[i])return a[i]<b[i];return false;}void put(std::uint8_t*out,std::size_t at,std::int64_t x){auto b=static_cast<std::uint64_t>(x);for(int i=0;i<8;++i){out[at+i]=static_cast<std::uint8_t>(b);b>>=8;}}}
extern "C" std::int64_t weighted_popular_matching(const std::int64_t*v,std::size_t length,std::uint8_t*out,std::size_t cap){if(!v||length<4||length>22||v[0]<1||v[0]>4||v[1]<1||v[1]>4)return -1;auto n=static_cast<std::size_t>(v[0]),m=static_cast<std::size_t>(v[1]);if(length!=2+n+n*m)return -1;for(std::size_t i=0;i<n;++i){if(v[2+i]<1||v[2+i]>1000)return -1;unsigned seen=0;for(std::size_t j=0;j<m;++j){auto r=v[2+n+i*m+j];if(r<0||r>=static_cast<std::int64_t>(m)||(seen>>(r))&1u)return -1;seen|=1u<<r;}}
 std::uint64_t total=1;for(std::size_t i=0;i<n;++i)total*=m+1;int best_card=-1,best[N]={-1,-1,-1,-1};for(std::uint64_t code=0;code<total;++code){int cand[N]{};if(!decode(code,n,m,cand))continue;bool popular=true;for(std::uint64_t other_code=0;other_code<total&&popular;++other_code){int other[N]{};if(!decode(other_code,n,m,other))continue;std::int64_t score=0;for(std::size_t i=0;i<n;++i){int rc=cand[i]<0?static_cast<int>(m):static_cast<int>(v[2+n+i*m+static_cast<std::size_t>(cand[i])]);int ro=other[i]<0?static_cast<int>(m):static_cast<int>(v[2+n+i*m+static_cast<std::size_t>(other[i])]);if(ro<rc)score+=v[2+i];else if(ro>rc)score-=v[2+i];}if(score>0)popular=false;}if(popular){int card=0;for(std::size_t i=0;i<n;++i)if(cand[i]>=0)++card;if(card>best_card||(card==best_card&&lexless(cand,best,n))){best_card=card;for(std::size_t i=0;i<n;++i)best[i]=cand[i];}}}
 std::int64_t fields[F]{};fields[0]=best_card<0?0:1;fields[1]=best_card<0?0:best_card;for(std::size_t i=0;i<n;++i)fields[2+i]=best_card<0?-1:best[i];auto bytes=8*(n+2);if(!out||cap<bytes)return -2;for(std::size_t i=0;i<n+2;++i)put(out,8*i,fields[i]);return static_cast<std::int64_t>(bytes);}
